messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low-Poly Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <!-- Import Map for Three.js r160 -->
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- SCENE SETUP ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        // Side-on camera position
        camera.position.set(0, 2, 12); 
        camera.lookAt(0, 1.5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- LIGHTING ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 7);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- MATERIALS ---
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.5 });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.7 });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.7 });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0xeeeeee, roughness: 0.4 });
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8 });

        // --- GEOMETRY HELPERS ---
        function createLimb(width, height, depth, mat) {
            const geo = new THREE.BoxGeometry(width, height, depth);
            // Offset geometry so pivot is at the top
            geo.translate(0, -height / 2, 0);
            const mesh = new THREE.Mesh(geo, mat);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // --- HUMANOID CONSTRUCTION ---
        const character = new THREE.Group();
        // Center the character vertically roughly around Y=0, but feet at Y=0
        character.position.y = 0; 

        // 1. Torso
        const torso = createLimb(0.7, 1.0, 0.4, shirtMat);
        torso.position.y = 1.5; // Hips are at 1.0, so torso sits on top
        character.add(torso);

        // Belt (visual detail)
        const belt = createLimb(0.72, 0.15, 0.42, beltMat);
        belt.position.y = 1.0;
        character.add(belt);

        // 2. Head
        const headGeo = new THREE.BoxGeometry(0.45, 0.5, 0.45);
        headGeo.translate(0, 0.25, 0); // Pivot at bottom
        const head = new THREE.Mesh(headGeo, skinMat);
        head.position.y = 2.25; // Top of torso (2.0) + half head
        head.castShadow = true;
        character.add(head);

        // 3. Arms
        // Left Arm
        const lArmGroup = new THREE.Group();
        lArmGroup.position.set(-0.45, 1.9, 0); // Shoulder position
        const lUpperArm = createLimb(0.2, 0.6, 0.2, skinMat);
        lArmGroup.add(lUpperArm);

        const lForearmGroup = new THREE.Group();
        lForearmGroup.position.set(0, -0.6, 0); // Elbow
        const lForearm = createLimb(0.18, 0.55, 0.18, skinMat);
        lForearmGroup.add(lForearm);
        lArmGroup.add(lForearmGroup);
        character.add(lArmGroup);

        // Right Arm
        const rArmGroup = new THREE.Group();
        rArmGroup.position.set(0.45, 1.9, 0);
        const rUpperArm = createLimb(0.2, 0.6, 0.2, skinMat);
        rArmGroup.add(rUpperArm);

        const rForearmGroup = new THREE.Group();
        rForearmGroup.position.set(0, -0.6, 0);
        const rForearm = createLimb(0.18, 0.55, 0.18, skinMat);
        rForearmGroup.add(rForearm);
        rArmGroup.add(rForearmGroup);
        character.add(rArmGroup);

        // 4. Legs
        // Left Leg
        const lLegGroup = new THREE.Group();
        lLegGroup.position.set(-0.2, 1.0, 0); // Hip position
        const lThigh = createLimb(0.25, 0.7, 0.25, pantsMat);
        lLegGroup.add(lThigh);

        const lShinGroup = new THREE.Group();
        lShinGroup.position.set(0, -0.7, 0); // Knee
        const lShin = createLimb(0.22, 0.7, 0.22, pantsMat);
        lShinGroup.add(lShin);

        // Shoe
        const lShoeGeo = new THREE.BoxGeometry(0.24, 0.15, 0.45);
        lShoeGeo.translate(0.05, -0.075, 0.1); // Offset for foot shape
        const lShoe = new THREE.Mesh(lShoeGeo, shoeMat);
        lShoe.position.set(0, -0.7, 0); // At ankle
        lShoe.castShadow = true;
        lShinGroup.add(lShoe);

        lLegGroup.add(lShinGroup);
        character.add(lLegGroup);

        // Right Leg
        const rLegGroup = new THREE.Group();
        rLegGroup.position.set(0.2, 1.0, 0);
        const rThigh = createLimb(0.25, 0.7, 0.25, pantsMat);
        rLegGroup.add(rThigh);

        const rShinGroup = new THREE.Group();
        rShinGroup.position.set(0, -0.7, 0);
        const rShin = createLimb(0.22, 0.7, 0.22, pantsMat);
        rShinGroup.add(rShin);

        const rShoeGeo = new THREE.BoxGeometry(0.24, 0.15, 0.45);
        rShoeGeo.translate(0.05, -0.075, 0.1);
        const rShoe = new THREE.Mesh(rShoeGeo, shoeMat);
        rShoe.position.set(0, -0.7, 0);
        rShoe.castShadow = true;
        rShinGroup.add(rShoe);

        rLegGroup.add(rShinGroup);
        character.add(rLegGroup);

        scene.add(character);

        // --- TREADMILL ---
        const treadmillGroup = new THREE.Group();

        // The Belt
        const beltGeo = new THREE.BoxGeometry(3, 0.1, 4);
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.receiveShadow = true;
        treadmillGroup.add(belt);

        // Side rails
        const railGeo = new THREE.BoxGeometry(0.2, 0.5, 4.2);
        const railMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const lRail = new THREE.Mesh(railGeo, railMat);
        lRail.position.set(-1.6, 0.25, 0);
        lRail.castShadow = true;
        treadmillGroup.add(lRail);

        const rRail = new THREE.Mesh(railGeo, railMat);
        rRail.position.set(1.6, 0.25, 0);
        rRail.castShadow = true;
        treadmillGroup.add(rRail);

        // Belt stripes (to visualize movement)
        const stripeGeo = new THREE.BoxGeometry(2.8, 0.01, 0.1);
        const stripeMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const stripes = [];
        for(let i=0; i<10; i++) {
            const s = new THREE.Mesh(stripeGeo, stripeMat);
            s.position.z = -1.8 + (i * 0.4);
            treadmillGroup.add(s);
            stripes.push(s);
        }

        scene.add(treadmillGroup);

        // --- ANIMATION LOGIC ---

        const CYCLE_DURATION = 10; // seconds
        const STAND_START = 0;
        const STAND_END = 2;

        const WALK_START = 2;
        const WALK_END = 5;

        const RUN_START = 5;
        const RUN_END = 8;

        const STAND_END_2 = 10; // 8 to 10

        // Helper to map time to 0..1
        function getPhase(time, start, end) {
            if (time < start) return 0;
            if (time > end) return 1;
            return (time - start) / (end - start);
        }

        // Helper for sine wave movement
        // Returns rotation value based on phase (0-1) and frequency
        function getLimbSwing(phase, frequency, offset = 0) {
            return Math.sin((phase * frequency * Math.PI * 2) + offset);
        }

        // Animation Loop
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            // Loop time within 10 seconds
            const loopTime = time % CYCLE_DURATION;

            // Determine current state
            let state = 'stand';
            if (loopTime >= WALK_START && loopTime < RUN_START) state = 'walk';
            if (loopTime >= RUN_START && loopTime < STAND_END_2) state = 'run';

            // Calculate local phases within the specific state duration
            // We want the animation to feel continuous within the state, 
            // but reset or start smoothly. Since we use Math.sin with phase 0-1, 
            // it starts at 0.

            let walkPhase = 0;
            let runPhase = 0;
            let bodyTilt = 0;
            let strideHeight = 0;

            if (state === 'walk') {
                walkPhase = getPhase(loopTime, WALK_START, WALK_END);
                // Walking parameters
                bodyTilt = 0; // Upright
                strideHeight = 0.1; // Moderate lift
            } else if (state === 'run') {
                runPhase = getPhase(loopTime, RUN_START, RUN_END);
                // Running parameters
                bodyTilt = 0.15; // Forward lean (radians)
                strideHeight = 0.25; // Higher lift
            }

            // --- APPLY ANIMATION ---

            // 1. Body Tilt (Torso and Head)
            // Smoothly interpolate tilt based on state
            let targetTilt = 0;
            if (state === 'run') targetTilt = bodyTilt;

            // Simple lerp for smooth transition between states
            character.rotation.z = THREE.MathUtils.lerp(character.rotation.z, -targetTilt, 0.1);

            // 2. Legs
            // Frequency: Walk ~3Hz, Run ~6Hz (visual approximation)
            // Amplitude: Walk ~1.0 rad, Run ~1.5 rad

            const legFreq = state === 'run' ? 6 : 3;
            const legAmp = state === 'run' ? 1.4 : 0.9;

            // Left Leg
            // Swing forward and back
            const lAngle = Math.sin(walkPhase * Math.PI * 2) * legAmp;
            // Note: We only update rotation if we are in the specific state, 
            // otherwise we need to hold the value or return to 0.
            // To make it look like a cycle, we just calculate based on current phase.
            // But wait, if we switch from Walk to Run, the sine wave phase resets.
            // This might look like a "jump" if not careful.
            // However, the prompt implies distinct phases.

            // To prevent snapping, we only rotate if the state is active.
            // Actually, let's just set the rotation based on the current state's math.

            if (state === 'stand') {
                // Return to 0
                lLegGroup.rotation.x = THREE.MathUtils.lerp(lLegGroup.rotation.x, 0, 0.1);
                rLegGroup.rotation.x = THREE.MathUtils.lerp(rLegGroup.rotation.x, 0, 0.1);
            } else {
                // Calculate target angles
                // We use the phase 0-1 to drive the sine wave.
                // To make it look like continuous movement within the state:
                // We need to accumulate time? No, simpler to just use phase.
                // The issue is the start of the sine wave is 0.

                // Let's define the angle based on phase
                // Walk: 3 cycles in 3 seconds -> 1 cycle per second.
                // Run: 6 cycles in 3 seconds -> 2 cycles per second.

                const angle = Math.sin(walkPhase * Math.PI * 2 * (state === 'run' ? 2 : 1)) * legAmp;

                lLegGroup.rotation.x = THREE.MathUtils.lerp(lLegGroup.rotation.x, angle, 0.2);

                // Right leg opposite
                const rAngle = Math.sin(walkPhase * Math.PI * 2 * (state === 'run' ? 2 : 1) + Math.PI) * legAmp;
                rLegGroup.rotation.x = THREE.MathUtils.lerp(rLegGroup.rotation.x, rAngle, 0.2);
            }

            // Knees (Shins)
            // Knees bend when leg swings back (roughly)
            const kneeAmp = state === 'run' ? 1.2 : 0.6;

            if (state === 'stand') {
                lShinGroup.rotation.x = THREE.MathUtils.lerp(lShinGroup.rotation.x, 0, 0.1);
                rShinGroup.rotation.x = THREE.MathUtils.lerp(rShinGroup.rotation.x, 0, 0.1);
            } else {
                // Simple approximation: bend knees when thigh is swinging back
                // sin > 0 is forward (usually), sin < 0 is back.
                // Let's just bend based on the thigh angle to simulate weight transfer
                const kneeTarget = Math.max(0, -lLegGroup.rotation.x) * kneeAmp;
                lShinGroup.rotation.x = THREE.MathUtils.lerp(lShinGroup.rotation.x, kneeTarget, 0.2);

                const rKneeTarget = Math.max(0, -rLegGroup.rotation.x) * kneeAmp;
                rShinGroup.rotation.x = THREE.MathUtils.lerp(rShinGroup.rotation.x, rKneeTarget, 0.2);
            }

            // 3. Arms (Opposite to legs)
            if (state === 'stand') {
                lArmGroup.rotation.x = THREE.MathUtils.lerp(lArmGroup.rotation.x, 0, 0.1);
                rArmGroup.rotation.x = THREE.MathUtils.lerp(rArmGroup.rotation.x, 0, 0.1);
                // Slight rest pose
                lArmGroup.rotation.z = 0.1;
                rArmGroup.rotation.z = -0.1;
            } else {
                // Arms swing opposite to legs
                const armAmp = state === 'run' ? 1.2 : 0.7;
                const armFreq = state === 'run' ? 2 : 1; // Same frequency as legs

                // Left arm opposite to left leg
                const lArmAngle = Math.sin(walkPhase * Math.PI * 2 * armFreq + Math.PI) * armAmp;
                lArmGroup.rotation.x = THREE.MathUtils.lerp(lArmGroup.rotation.x, lArmAngle, 0.2);

                // Right arm opposite to right leg
                const rArmAngle = Math.sin(walkPhase * Math.PI * 2 * armFreq + Math.PI + Math.PI) * armAmp;
                rArmGroup.rotation.x = THREE.MathUtils.lerp(rArmGroup.rotation.x, rArmAngle, 0.2);

                // Elbows bend slightly during run
                const elbowBend = state === 'run' ? 0.8 : 0.2;
                // Bend elbows when arm is swinging back
                lForearmGroup.rotation.x = Math.max(0, -lArmGroup.rotation.x) * elbowBend;
                rForearmGroup.rotation.x = Math.max(0, -rArmGroup.rotation.x) * elbowBend;
            }

            // 4. Treadmill Belt Visuals
            // Move stripes
            let speed = 0;
            if (state === 'walk') speed = 2;
            if (state === 'run') speed = 5;

            stripes.forEach(s => {
                s.position.z += speed * 0.016; // Approx 60fps
                if (s.position.z > 2) s.position.z -= 4;
            });

            // 5. Body Bobbing (Vertical)
            // Running has more bob
            let bobAmount = 0;
            let bobFreq = 0;
            if (state === 'walk') {
                bobAmount = 0.05;
                bobFreq = 2; // Twice per cycle (left/right step)
            } else if (state === 'run') {
                bobAmount = 0.15;
                bobFreq = 4; 
            }

            if (state !== 'stand') {
                // Bob up and down
                // We add this to Y position
                // Note: This modifies the character group Y, which might interfere with feet on ground?
                // No, the feet pivot at the hip, so the feet will lift.
                // To keep feet on ground, we should translate the whole character down when legs lift?
                // Too complex for low poly. Simple bobbing is usually fine for side view if subtle.
                // Let's just bob the torso/head slightly or accept slight foot sliding.
                // Actually, let's just bob the whole character Y.
                // To prevent floating, we clamp.
                const bob = Math.sin(walkPhase * Math.PI * 2 * bobFreq) * bobAmount;
                // We don't want to override the hip height completely.
                // Let's just add a small Y offset.
                character.position.y = bob; 
            } else {
                character.position.y = THREE.MathUtils.lerp(character.position.y, 0, 0.1);
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
